from part2 import D, B
B['w6']={'name':'Week 6 · File I/O','drills':[
 D('Append and read names','M4',['open/with','append mode','sorted'],'add_name(path, name) appends name plus a newline to the file. read_names(path) returns the names as a sorted list with the newlines stripped.','def add_name(path, name):\n    pass\n\ndef read_names(path):\n    pass\n','import os\np="/tmp/de_names.txt"\nos.path.exists(p) and os.remove(p)\nadd_name(p,"Ron"); add_name(p,"Harry"); add_name(p,"Hermione")\nassert read_names(p)==["Harry","Hermione","Ron"]\nassert open(p).read()=="Ron\\nHarry\\nHermione\\n"','def add_name(path, name):\n    with open(path, "a") as file:\n        file.write(f"{name}\\n")\n\ndef read_names(path):\n    names = []\n    with open(path) as file:\n        for line in file:\n            names.append(line.rstrip())\n    return sorted(names)\n',['Mode "a" appends; write() adds no newline for you.','line.rstrip() removes the trailing newline.']),
 D('FIX THE BUG: the vanishing log','M4',['open modes','debugging'],'log_line should ADD a line each call, but the earlier lines vanish. Fix it.','def log_line(path, text):\n    with open(path, "w") as f:\n        f.write(text + "\\n")\n','import os\np="/tmp/de_log.txt"\nos.path.exists(p) and os.remove(p)\nlog_line(p,"first"); log_line(p,"second")\nassert open(p).read()=="first\\nsecond\\n","earlier lines were lost"','def log_line(path, text):\n    with open(path, "a") as f:\n        f.write(text + "\\n")\n',['"w" recreates the file every time it opens.','Change the mode to "a".'],'fix'),
 D('Read a CSV safely','M4',['csv.DictReader','quoted commas'],'load_students(path) reads a CSV with header name,home and returns a list of dicts. A home may contain a comma inside quotes, so do not split on commas yourself.','import csv\n\ndef load_students(path):\n    pass\n','p="/tmp/de_students.csv"\nopen(p,"w").write(\'name,home\\nHarry,"Number Four, Privet Drive"\\nRon,The Burrow\\n\')\nr=load_students(p)\nassert r==[{"name":"Harry","home":"Number Four, Privet Drive"},{"name":"Ron","home":"The Burrow"}],r','import csv\n\ndef load_students(path):\n    with open(path) as file:\n        return list(csv.DictReader(file))\n',['csv.DictReader(file) yields one dict per row.','Wrap it in list(...) before the file closes.']),
 D('Sort with a key','M3',['sorted key','lambda','dict'],'sort_students(students, key="name", reverse=False) returns a NEW list sorted by that dict key. Do not change the original list.','def sort_students(students, key="name", reverse=False):\n    pass\n','st=[{"name":"Ron","home":"Burrow"},{"name":"Harry","home":"Privet"},{"name":"Draco","home":"Manor"}]\nassert [s["name"] for s in sort_students(st)]==["Draco","Harry","Ron"]\nassert [s["name"] for s in sort_students(st,key="home")]==["Ron","Draco","Harry"]\nassert [s["name"] for s in sort_students(st,reverse=True)]==["Ron","Harry","Draco"]\nassert [s["name"] for s in st]==["Ron","Harry","Draco"],"original was changed"','def sort_students(students, key="name", reverse=False):\n    return sorted(students, key=lambda s: s[key], reverse=reverse)\n',['sorted() returns a new list; .sort() changes in place.','key=lambda s: s[key]']),
 D('Write a CSV row','M4',['csv.DictWriter','append mode','os.path'],'save_student(path, name, home) appends one row. If the file is missing or empty, write the header name,home first. Quoting of commas must be automatic.','import csv, os\n\ndef save_student(path, name, home):\n    pass\n','p="/tmp/de_s2.csv"\nos.path.exists(p) and os.remove(p)\nsave_student(p,"Harry","Number Four, Privet Drive"); save_student(p,"Ron","The Burrow")\nassert open(p).readline().strip()=="name,home"\nassert load_students(p)==[{"name":"Harry","home":"Number Four, Privet Drive"},{"name":"Ron","home":"The Burrow"}]','import csv, os\n\ndef save_student(path, name, home):\n    is_new = not os.path.exists(path) or os.path.getsize(path) == 0\n    with open(path, "a", newline="") as file:\n        writer = csv.DictWriter(file, fieldnames=["name", "home"])\n        if is_new:\n            writer.writeheader()\n        writer.writerow({"name": name, "home": home})\n',['Decide is_new BEFORE opening in append mode.','writer.writeheader() then writer.writerow({...}).']),
 D('Roster lines (capstone)','M4',['composition','f-string format'],'roster_lines(path) returns "NAME is from HOME" strings for every student in the CSV, sorted by name. Reuse load_students and sort_students.','def roster_lines(path):\n    pass\n','p="/tmp/de_roster.csv"\nopen(p,"w").write(\'name,home\\nRon,The Burrow\\nHarry,"Number Four, Privet Drive"\\n\')\nassert roster_lines(p)==["Harry is from Number Four, Privet Drive","Ron is from The Burrow"]','def roster_lines(path):\n    return [f"{s[\'name\']} is from {s[\'home\']}" for s in sort_students(load_students(path))]\n',['Quotes inside an f-string must differ from the outer ones.','Compose: sort_students(load_students(path)).']),
]}
B['w7']={'name':'Week 7 · Regular Expressions','drills':[
 D('Validate an .edu email','M5',['re.search','anchors ^ $','IGNORECASE'],'valid_edu(email) returns True only for word characters, one @, word characters, then a literal .edu, with nothing before or after. Ignore case.','import re\n\ndef valid_edu(email):\n    pass\n','assert valid_edu("malan@harvard.edu") is True and valid_edu("MALAN@HARVARD.EDU") is True\nfor bad in ("malan@@@harvard.edu","my email is malan@harvard.edu.","@harvard.edu","malan@harvard.com","malan@.edu"):\n    assert valid_edu(bad) is False, bad','import re\n\ndef valid_edu(email):\n    return re.search(r"^\\w+@\\w+\\.edu$", email, re.IGNORECASE) is not None\n',['^ and $ pin the match to the whole string.','The dot before edu needs a backslash.']),
 D('FIX THE BUG: the unescaped dot','M5',['escaping','regex debugging'],'is_edu_domain accepts "harvard?edu". Fix the pattern so only a literal dot works.','import re\n\ndef is_edu_domain(domain):\n    return re.search(r"^\\w+.edu$", domain) is not None\n','assert is_edu_domain("harvard.edu") is True\nassert is_edu_domain("harvard?edu") is False and is_edu_domain("harvardxedu") is False','import re\n\ndef is_edu_domain(domain):\n    return re.search(r"^\\w+\\.edu$", domain) is not None\n',['In a pattern, a bare dot means ANY character.','Escape it with a backslash.'],'fix'),
 D('Optional subdomain','M5',['groups','? optional','* repeat'],'valid_edu_sub(email): like valid_edu, but the username may contain single dots (da.malan) and the domain may have ONE optional subdomain (cs50.harvard.edu). Ignore case.','import re\n\ndef valid_edu_sub(email):\n    pass\n','for good in ("malan@cs50.harvard.edu","malan@harvard.edu","da.malan@harvard.edu"):\n    assert valid_edu_sub(good) is True, good\nfor bad in ("malan@.harvard.edu","malan@a.b.harvard.edu","da..malan@harvard.edu"):\n    assert valid_edu_sub(bad) is False, bad','import re\n\ndef valid_edu_sub(email):\n    return re.search(r"^\\w+(?:\\.\\w+)*@(?:\\w+\\.)?\\w+\\.edu$", email, re.IGNORECASE) is not None\n',['Parentheses group; a ? after a group makes the whole group optional.','Username: \\w+ then a repeated group of dot plus \\w+.']),
 D('Flip a name','M5',['capture groups','re.search','strip'],'fix_name(name): "Malan, David" becomes "David Malan". Tolerate a missing or extra space after the comma and stray outer spaces. A name with no comma comes back unchanged (stripped).','import re\n\ndef fix_name(name):\n    pass\n','assert fix_name("Malan, David")=="David Malan" and fix_name("Malan,David")=="David Malan"\nassert fix_name(" Malan,   David ")=="David Malan" and fix_name("David Malan")=="David Malan"','import re\n\ndef fix_name(name):\n    name = name.strip()\n    matches = re.search(r"^(.+?)\\s*,\\s*(.+)$", name)\n    if matches:\n        return f"{matches.group(2)} {matches.group(1)}"\n    return name\n',['Group 1 is the first set of parentheses, not group 0.','\\s* tolerates zero or more spaces.']),
 D('Mask the digits','M5',['re.sub','\\d'],'mask_digits(text): replace every run of digits with a single "#". "call 555-1234 now" becomes "call #-# now".','import re\n\ndef mask_digits(text):\n    pass\n','assert mask_digits("call 555-1234 now")=="call #-# now"\nassert mask_digits("no digits")=="no digits" and mask_digits("a1b22c333")=="a#b#c#"','import re\n\ndef mask_digits(text):\n    return re.sub(r"\\d+", "#", text)\n',['re.sub(pattern, replacement, text)','\\d+ means one or more digits.']),
 D('Profile username','M5',['optional groups','character class','non-capturing'],'github_username(url) returns the username from a profile URL, or None. Accept an optional http(s)://, an optional www., any letter case, and one optional trailing slash. Usernames use letters, digits, and hyphens only. Anything extra (like /repo) means None.','import re\n\ndef github_username(url):\n    pass\n','assert github_username("https://github.com/octocat")=="octocat"\nassert github_username("http://www.github.com/octo-cat/")=="octo-cat"\nassert github_username("github.com/octocat")=="octocat"\nassert github_username("HTTPS://GITHUB.COM/Octocat")=="Octocat"\nfor bad in ("https://gitlab.com/octocat","https://github.com/","https://github.com/octocat/repo"):\n    assert github_username(bad) is None, bad','import re\n\ndef github_username(url):\n    matches = re.search(r"^(?:https?://)?(?:www\\.)?github\\.com/([a-z0-9-]+)/?$", url, re.IGNORECASE)\n    return matches.group(1) if matches else None\n',['A group written (?:...) does not capture; only the username gets plain parentheses.','Put the hyphen last in the character class so it is literal.']),
 D('Clean roster (capstone)','M5',['composition','re','dedupe'],'normalize_roster(lines): fix every non-blank line with fix_name, drop duplicates, return the names sorted.','def normalize_roster(lines):\n    pass\n','r=normalize_roster([" Malan, David","Potter,Harry","","Harry Potter","Granger, Hermione"])\nassert r==["David Malan","Harry Potter","Hermione Granger"],r','def normalize_roster(lines):\n    names = [fix_name(line) for line in lines if line.strip()]\n    return sorted(set(names))\n',['Skip blank lines with a condition in the comprehension.','set() removes duplicates; sorted() orders them.']),
]}
if __name__=='__main__':
    import json
    json.dump(B,open('drill_banks_src.json','w',encoding='utf-8'),ensure_ascii=False,indent=1)
    print({k:len(v['drills']) for k,v in B.items()},sum(len(v['drills']) for v in B.values()),'drills')
